inline double next_layer_id(flight::Array<flight::Ref<TiledLayer>> layers) {
  double max = 0.0;
  for (auto layer : layers) {
    if ((std::visit([](const auto& value) { return value->id; }, layer) > max)) {
      (max = std::visit([](const auto& value) { return value->id; }, layer));
    }
    if (layer.index() == 1) {
      (max = flight::maximum(max, (next_layer_id(std::get<1>(layer)->layers) - 1.0)));
    }
  }
  return (max + 1.0);
}

inline double next_object_id(flight::Array<flight::Ref<TiledLayer>> layers) {
  double max = 0.0;
  for (auto layer : layers) {
    if (layer.index() == 2) {
      for (auto object : std::get<2>(layer)->objects) {
        if ((object->id > max)) {
          (max = object->id);
        }
      }
    }
    if (layer.index() == 1) {
      (max = flight::maximum(max, (next_object_id(std::get<1>(layer)->layers) - 1.0)));
    }
  }
  return (max + 1.0);
}


